window.makeMeshyStoneHammerV211=(()=>{let geometry,material;return function(T){
if(!geometry){const decode=(s,C)=>{const b=Uint8Array.from(atob(s),c=>c.charCodeAt(0));return new C(b.buffer)};
geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(decode('',Float32Array),3));geometry.setAttribute('uv',new T.BufferAttribute(decode('',Float32Array),2));geometry.setIndex(new T.BufferAttribute(decode('',Uint32Array),1));geometry.computeVertexNormals();geometry.computeBoundingSphere();
const map=new T.TextureLoader().load('data:image/jpeg;base64,');map.colorSpace=T.SRGBColorSpace;material=new T.MeshStandardMaterial({map,roughness:.91});}
const g=new T.Group();g.name='Martelo_Meshy_Pedra_Original';const m=new T.Mesh(geometry,material);m.castShadow=m.receiveShadow=true;g.add(m);g.userData.source='Meshy_AI_Stone_Headed_Ceremoni_1015070401_texture.fbx';return g;};})();